-- Prescribed Hourly Rates transcribed from the original workbook-derived migration.
-- Regulatory Table 9(a) is represented as PUBLIC_LAW_CHILDREN; Table 9(b) as OTHER_FAMILY.
-- Table 9(aa) section-31 escape rates are not stored here because the simplified model does not yet include a CPGFS escape-hourly rate table.
SET search_path TO "${flyway:defaultSchema}";

ON CONFLICT (fee_scheme_version_id, case_category_id, court_level_id, location_id, activity_type_id, unit_type_id) DO UPDATE
SET amount = EXCLUDED.amount;
